            if (($tokens[$open] ?? null) !== '(') {
                continue;
            }

            return $this->value($tokens, $open + 1)['value'];
        }

        return null;
    }

    /**
     * Parses one literal value and returns the index after it.
     *
     * @param list<mixed> $tokens
     * @return array{value: mixed, index: int}
     */
