            $this->verify($change);
            if (!rename($temporary, $change->path)) {
                throw new PolicyException('Cannot replace ' . $change->path . '. Check directory permissions.');
            }
        } finally {
            if (is_file($temporary)) {
                unlink($temporary);
            }
        }
    }
