    public static function providerInvalidExtensions(): iterable
    {
        yield 'missing' => ['Missing\\GuardExtension', [], 'composer dump-autoload'];
        yield 'wrong contract' => [Registry::class, [], 'must implement Guard\\Extension\\Extension'];
